var doc = Document;
// Goal: the project lacks a component (here a 2 x 2 x 2 ft block); build it as a family, load it, place one.

// 1. Find a family template. Application.FamilyTemplatePath is the install's template root; the
//    template file's name is what decides the family's category (Generic Model here).
var app = UIApplication.Application;
string template = "";
foreach (var f in System.IO.Directory.EnumerateFiles(app.FamilyTemplatePath, "Generic Model.rft", System.IO.SearchOption.AllDirectories)) { template = f; break; }
if (template.Length == 0) { throw new System.Exception("no Generic Model.rft under " + app.FamilyTemplatePath); }

// 2. Create the family document through the connector (not Application.NewFamilyDocument, which
//    would leave the connector unaware of it). It opens headless; print the cleanup marker so the
//    caller can close it later -- Close is a lifecycle action needing confirmation, so it is not
//    done here.
var famDoc = Connector.CreateFamilyDocument(template);
System.Console.WriteLine("cleanup-title=" + famDoc.Title + ";");

// 3. Draw the geometry INSIDE a block on the family document. Family geometry is created through
//    famDoc.FamilyCreate (FamilyItemFactory), not doc.Create.
var extrusionCreated = Connector.WithTransaction(famDoc, () => {
  var plane = Autodesk.Revit.DB.Plane.CreateByNormalAndOrigin(Autodesk.Revit.DB.XYZ.BasisZ, Autodesk.Revit.DB.XYZ.Zero);
  var sketchPlane = Autodesk.Revit.DB.SketchPlane.Create(famDoc, plane);
  var p1 = new Autodesk.Revit.DB.XYZ(-1, -1, 0); var p2 = new Autodesk.Revit.DB.XYZ(1, -1, 0);
  var p3 = new Autodesk.Revit.DB.XYZ(1, 1, 0);   var p4 = new Autodesk.Revit.DB.XYZ(-1, 1, 0);
  var profile = new Autodesk.Revit.DB.CurveArray();
  profile.Append(Autodesk.Revit.DB.Line.CreateBound(p1, p2)); profile.Append(Autodesk.Revit.DB.Line.CreateBound(p2, p3));
  profile.Append(Autodesk.Revit.DB.Line.CreateBound(p3, p4)); profile.Append(Autodesk.Revit.DB.Line.CreateBound(p4, p1));
  var profiles = new Autodesk.Revit.DB.CurveArrArray(); profiles.Append(profile);
  var extrusion = famDoc.FamilyCreate.NewExtrusion(true, profiles, sketchPlane, 2.0);
  famDoc.Regenerate();
  return extrusion != null;
});

// 4. Load it into the project BETWEEN blocks. LoadFamily manages its own transaction and requires
//    the TARGET document to have no open transaction; inside Connector.WithTransaction(doc, ...) it
//    fails with script-target-must-not-be-modifiable. The family document itself may still be
//    unsaved and even modifiable -- only the target matters. Loading from a separate, earlier call
//    works the same way (find the family document by Title through UIApplication.Application.Documents).
var family = famDoc.LoadFamily(doc);
if (family == null) { throw new System.Exception("LoadFamily returned null (a family of the same name may already be loaded)"); }

// 5. Place an instance INSIDE a block on the project. A FamilySymbol must be Activate()d before its
//    first placement or NewFamilyInstance throws; the point-based overload suits a non-hosted
//    generic model. Compare the count after with the count before, not against an absolute.
var before = new Autodesk.Revit.DB.FilteredElementCollector(doc).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_GenericModel).WhereElementIsNotElementType().GetElementCount();
return Connector.WithTransaction(doc, () => {
  Autodesk.Revit.DB.FamilySymbol symbol = null;
  foreach (Autodesk.Revit.DB.ElementId symId in family.GetFamilySymbolIds()) { symbol = doc.GetElement(symId) as Autodesk.Revit.DB.FamilySymbol; break; }
  if (!symbol.IsActive) { symbol.Activate(); }
  doc.Regenerate();
  var instance = doc.Create.NewFamilyInstance(new Autodesk.Revit.DB.XYZ(5, 5, 0), symbol, Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  doc.Regenerate();
  var after = new Autodesk.Revit.DB.FilteredElementCollector(doc).OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_GenericModel).WhereElementIsNotElementType().GetElementCount();

  // 6. Verify: the family is in the project by name and the instance's symbol belongs to it.
  var familyPresent = doc.GetElement(family.Id) is Autodesk.Revit.DB.Family;
  return new { familyName = family.Name, familyPresent, extrusionCreated, symbolId = symbol.Id.Value, instanceId = instance.Id.Value, symbolBelongsToFamily = instance.Symbol.Family.Id == family.Id, placed = after - before };
});
